import { Component, OnInit } from '@angular/core';
import { JobService } from '../../../core/services/job.service';
import { AuthService } from '../../../core/services/auth.service';
import { ToastService } from '../../../core/services/toast.service';
import { Job } from '../../../core/models/job.model';

@Component({
  selector: 'app-manage-jobs',
  templateUrl: './manage-jobs.component.html',
  styleUrls: ['./manage-jobs.component.css']
})
export class ManageJobsComponent implements OnInit {
  jobs: Job[] = [];
  isLoading = true;
  jobToDelete: Job | null = null;
  isConfirmModalOpen = false;

  constructor(
    private jobService: JobService,
    private authService: AuthService,
    private toast: ToastService
  ) {}

  ngOnInit(): void {
    this.loadJobs();
  }

  loadJobs(): void {
    this.isLoading = true;
    this.jobService.getAllJobs().subscribe({
      next: (res) => {
        const currentUserId = this.authService.getUserId();
        const role = this.authService.getUserRole();
        if (role === 'admin') {
          this.jobs = res.data;
        } else {
          this.jobs = res.data.filter(j => {
            const empId = typeof j.employer === 'object' ? j.employer?._id : j.employer;
            return empId === currentUserId;
          });
        }
        this.isLoading = false;
      },
      error: () => {
        this.isLoading = false;
      }
    });
  }

  confirmDelete(job: Job): void {
    this.jobToDelete = job;
    this.isConfirmModalOpen = true;
  }

  onDeleteConfirmed(): void {
    if (!this.jobToDelete) return;
    const id = this.jobToDelete._id || this.jobToDelete.id;
    if (!id) return;

    this.jobService.deleteJob(id).subscribe({
      next: () => {
        this.toast.success('Job Deleted', 'The job posting was successfully removed.');
        this.isConfirmModalOpen = false;
        this.jobToDelete = null;
        this.loadJobs();
      },
      error: (err) => {
        this.toast.error('Error', err.error?.message || 'Failed to delete job.');
        this.isConfirmModalOpen = false;
      }
    });
  }

  onDeleteCancelled(): void {
    this.isConfirmModalOpen = false;
    this.jobToDelete = null;
  }
}
<div class="container section-padding">
  <div class="d-flex justify-content-between align-items-center mb-4">
    <div>
      <h1 class="page-title">Manage Job Postings</h1>
      <p class="page-subtitle">Track, review, and manage your posted opportunities.</p>
    </div>
    <a routerLink="/jobs/create" class="btn btn-primary">
      <i class="fa-solid fa-plus"></i> Post New Job
    </a>
  </div>

  <app-loading-spinner *ngIf="isLoading"></app-loading-spinner>

  <ng-container *ngIf="!isLoading">
    <div *ngIf="jobs.length === 0" class="card text-center p-5">
      <i class="fa-solid fa-briefcase text-muted mb-3" style="font-size: 3rem;"></i>
      <h3>No Job Postings Yet</h3>
      <p class="text-muted">You haven't posted any jobs yet. Create your first listing to start receiving applications.</p>
      <div class="mt-3">
        <a routerLink="/jobs/create" class="btn btn-primary">Post a Job Opening</a>
      </div>
    </div>

    <div *ngIf="jobs.length > 0" class="jobs-table-card card">
      <div class="table-responsive">
        <table class="table">
          <thead>
            <tr>
              <th>Job Title</th>
              <th>Company</th>
              <th>Type</th>
              <th>Location</th>
              <th>Salary</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let job of jobs">
              <td class="font-bold">
                <a [routerLink]="['/jobs', job._id || job.id]" class="text-slate-900 hover:text-primary">
                  {{ job.title }}
                </a>
              </td>
              <td>{{ job.companyName }}</td>
              <td><span class="badge badge-primary">{{ job.type }}</span></td>
              <td>{{ job.location }}</td>
              <td>{{ job.salary ? ('$' + job.salary.toLocaleString() + '/yr') : 'Negotiable' }}</td>
              <td>
                <div class="action-btn-group">
                  <a [routerLink]="['/jobs', job._id || job.id, 'applications']" class="btn btn-sm btn-outline" title="View Applications">
                    <i class="fa-solid fa-users"></i>
                  </a>
                  <a [routerLink]="['/jobs', job._id || job.id, 'edit']" class="btn btn-sm btn-secondary" title="Edit Job">
                    <i class="fa-solid fa-pen-to-square"></i>
                  </a>
                  <button (click)="confirmDelete(job)" class="btn btn-sm btn-danger" title="Delete Job">
                    <i class="fa-solid fa-trash-can"></i>
                  </button>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </ng-container>
</div>

<app-confirm-modal
  [isOpen]="isConfirmModalOpen"
  title="Delete Job Posting"
  message="Are you sure you want to delete this job posting? This action cannot be undone."
  confirmText="Delete"
  cancelText="Cancel"
  (confirm)="onDeleteConfirmed()"
  (cancel)="onDeleteCancelled()">
</app-confirm-modal>
